import {readFileSync} from 'node:fs';
export const hrrrNow=Date.parse('2026-10-29T03:00:00Z'),hrrrIssued=hrrrNow-3*3600000;
export const metadata=JSON.parse(readFileSync(new URL('./hrrr-metadata.json',import.meta.url),'utf8'));
export function rawBlosc(values,integer=false){const bytes=new Uint8Array(values.length*8+16),v=new DataView(bytes.buffer);bytes.set([2,1,35,8]);v.setUint32(4,values.length*8,true);v.setUint32(8,values.length*8,true);v.setUint32(12,bytes.length,true);values.forEach((n,i)=>integer?v.setBigInt64(16+i*8,BigInt(n),true):v.setFloat64(16+i*8,n,true));return bytes;}
export function fakeHrrr(){let fail=null,calls=[];const fetcher=async(url,options)=>{calls.push(url);if(options.redirect!=='manual')throw Error('Redirect must not follow');if(fail==='all')return new Response('down',{status:503});if(url.endsWith('/.zmetadata'))return Response.json(metadata);if(url.endsWith('/forecast_reference_time/0')){const b=new Uint8Array(8);new DataView(b.buffer).setFloat64(0,hrrrIssued/3600000,true);return new Response(b);}if(url.endsWith('/time/0'))return new Response(rawBlosc(Array.from({length:48},(_,i)=>hrrrIssued/3600000+i+1)));if(url.endsWith('/forecast_period/0'))return new Response(rawBlosc(Array.from({length:48},(_,i)=>i+1),true));for(const [axis,count,origin] of [['x',1799,-2697520.1425219304],['y',1059,-1587306.152557]] )if(url.endsWith('/projection_'+axis+'_coordinate/0'))return new Response(rawBlosc(Array.from({length:count},(_,i)=>origin+i*3000)));if(fail==='chunk')return new Response('missing',{status:404});return new Response(rawBlosc(Array(48*150*150).fill(2.5e-9)));};return {fetcher,calls,fail:v=>fail=v};}
export function hrrrProduct(){return {method:'2026-10-29.1',point:{lat:39,lon:-77},issued_at:new Date(hrrrIssued).toISOString(),checked_at:new Date(hrrrNow).toISOString(),raw_unit:'kg/m³',conversion_factor:1e9,height_m:8,temporal_semantics:'instantaneous',cell:{lat:38.99566,lon:-76.99582,x:1485,y:613,projection_distance_m:603},samples:Array.from({length:48},(_,i)=>({at:new Date(hrrrIssued+(i+1)*3600000).toISOString(),lead_hours:i+1,raw_value:2.5e-9}))};}
export function rapProduct(){const rasters=Array.from({length:52},(_,i)=>({objectid:i+1,idp_subset:'conus',idp_issueddate:hrrrIssued,idp_validtime:hrrrIssued+i*3600000}));return {method:'2026-10-28.1',point:{lat:39,lon:-77},issued_at:new Date(hrrrIssued).toISOString(),checked_at:new Date(hrrrNow).toISOString(),raw_unit:'kg/m³',conversion_factor:1e9,temporal_semantics:'instantaneous',rasters,samples:rasters.map(a=>({rasterId:a.objectid,attributes:a,location:{x:-77,y:39,spatialReference:{wkid:4326}},value:'0.000000001'}))};}
